arguments.content:
:root {
  --bg: #1a1d21;
  --panel: #22262b;
  --panel2: #2a2f35;
  --border: #3a4047;
  --text: #d6dade;
  --dim: #8a929b;
  --accent: #4da3ff;
  --accent2: #7ee2a8;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font: 13px/1.4 "Segoe UI", system-ui, sans-serif;
  user-select: none;
}

body { display: flex; flex-direction: column; }

/* ---- top bar ---- */
#topbar {
  display: flex; align-items: center; gap: 4px;
  padding: 4px 8px;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
}
.brand { font-weight: 700; letter-spacing: 2px; color: var(--accent); margin-right: 6px; }
.sep { width: 1px; height: 18px; background: var(--border); margin: 0 6px; }

button {
  background: var(--panel2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 4px 10px;
  cursor: pointer;
  font: inherit;
}
button:hover { background: #343a42; border-color: #4a525b; }
button:active { background: #3c434c; }

/* ---- main layout ---- */
#main { flex: 1; display: flex; min-height: 0; }

#tools {
  display: flex; flex-direction: column; gap: 4px;
  padding: 6px 4px;
  background: var(--panel);
  border-right: 1px solid var(--border);
}
.tool {
  position: relative;
  width: 40px; height: 40px;
  font-size: 17px;
  display: flex; align-items: center; justify-content: center;
}
.tool label {
  position: absolute; right: 3px; bottom: 1px;
  font-size: 9px; color: var(--dim); pointer-events: none;
}
.tool.active { background: var(--accent); border-color: var(--accent); color: #10131a; }
.tool.active label { color: #10131a; }

#viewport { flex: 1; position: relative; min-width: 0; }
#canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: crosshair; }

/* ---- help overlay ---- */
#help {
  position: absolute; top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 18px 24px;
  box-shadow: 0 8px 30px rgba(0,0,0,.5);
  z-index: 10;
}
#help h2 { font-size: 14px; margin-bottom: 10px; color: var(--accent); }
#help td { padding: 2px 14px 2px 0; }
#help td:first-child { color: var(--accent2); font-family: Consolas, monospace; font-size: 12px; }
#help p { margin-top: 10px; color: var(--dim); font-size: 11px; }

/* ---- sidebar ---- */
#sidebar {
  width: 220px;
  background: var(--panel);
  border-left: 1px solid var(--border);
  overflow-y: auto;
  display: flex; flex-direction: column;
}
.panel { padding: 8px 10px; border-bottom: 1px solid var(--border); }
.panel h3 {
  font-size: 11px; text-transform: uppercase; letter-spacing: 1px;
  color: var(--dim); margin-bottom: 6px;
  display: flex; justify-content: space-between; align-items: center;
}
.panel h3 button { padding: 0 7px; line-height: 16px; }

.layer-row {
  display: flex; align-items: center; gap: 6px;
  padding: 3px 4px; border-radius: 4px; cursor: pointer;
}
.layer-row:hover { background: var(--panel2); }
.layer-row.active { background: var(--panel2); outline: 1px solid var(--accent); }
.layer-row .vis { cursor: pointer; width: 16px; text-align: center; }
.layer-row .vis.off { opacity: .25; }
.layer-row input[type="color"] {
  width: 18px; height: 18px; padding: 0; border: none; background: none; cursor: pointer;
}
.layer-row .lname { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.layer-row .del { color: var(--dim); padding: 0 4px; border: none; background: none; }
.layer-row .del:hover { color: #ff7b72; }

#props .prow { display: flex; align-items: center; gap: 6px; margin-bottom: 5px; }
#props .prow label { width: 60px; color: var(--dim); font-size: 12px; }
#props input, #props select {
  flex: 1; min-width: 0;
  background: var(--bg); color: var(--text);
  border: 1px solid var(--border); border-radius: 3px;
  padding: 3px 6px; font: inherit;
}
#props input[type="color"] { padding: 0; height: 22px; }
.dim-text { color: var(--dim); }

/* ---- status bar ---- */
#status {
  display: flex; align-items: center; gap: 8px;
  padding: 3px 10px;
  background: var(--panel);
  border-top: 1px solid var(--border);
  font-family: Consolas, monospace; font-size: 12px;
}
#coords { min-width: 160px; color: var(--accent2); }
.stat-toggle { padding: 1px 8px; font-size: 11px; color: var(--dim); }
.stat-toggle.on { color: var(--accent); border-color: var(--accent); }
#hint { color: var(--dim); font-family: "Segoe UI", system-ui, sans-serif; }
